def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])

    # Infer the horizontal period from the patterned region, avoiding its
    # irregular left edge.
    scores = {}
    for p in range(2, 11):
        same = total = 0
        for r in range(3, h):
            for c in range(6, w - p):
                a, b = grid[r][c], grid[r][c + p]
                if a != 0 and b != 0:
                    total += 1
                    same += (a == b)
        scores[p] = same / total if total else 0
    period = max(scores, key=lambda p: (scores[p], -p))

    out = [row[:] for row in grid]

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue

            # Restore the constant top/left frame.
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4
            elif c >= 6:
                vals = [grid[r][x] for x in range(6, w)
                        if grid[r][x] != 0 and x % period == c % period]
                if vals:
                    out[r][c] = Counter(vals).most_common(1)[0][0]
            else:
                # The narrow patterned strip at the left follows the
                # same repeating sequence vertically.
                vals = [grid[y][c] for y in range(7, h)
                        if grid[y][c] != 0 and y % period == r % period]
                if vals:
                    out[r][c] = Counter(vals).most_common(1)[0][0]

    return out
